import { describe, it, expect } from 'vitest';
import { protoV4PoolKey, encodeArcV4ExactInSwap } from '../src';

const USDC = '0x3600000000000000000000000000000000000000';

/**
 * V4_SWAP input of a live Universal Router buy on Arc mainnet
 * (tx 0x0044c8a8fe9bc4f16bbf717414b53747408e98ebab70b6e0491e02e9d4c7da34).
 */
const LIVE_V4_SWAP_INPUT =
  '';

describe('Arc v4 swap encoding', () => {
  it('reproduces a live Universal Router swap byte-for-byte', () => {
    const { commands, inputs } = encodeArcV4ExactInSwap({
      poolKey: {
        currency0: USDC,
        currency1: '0x5849fd68a097b3ee7d87ce88a0fcbb76857648ff',
        fee: 0,
        tickSpacing: 200,
        hooks: '0x173c4bdd5cf95a935d2b5636c573c5f4df062044',
      },
      tokenIn: USDC,
      amountIn: 0xa815den,
      amountOutMinimum: 0x31ab49b39b5e17ae5bn,
    });
    expect(commands).toBe('0x10');
    expect(inputs).toEqual([LIVE_V4_SWAP_INPUT]);
  });

  it('sorts pool currencies by address', () => {
    const hook = '0x6c56E2f4febC9ba172Cba2d39CB88B4B5D8e60Cc';
    const high = protoV4PoolKey('0xc4354d6b63d07bD04714ea082E362Cd73dCbBFba', USDC, hook);
    expect(high.currency0).toBe(USDC);
    const low = protoV4PoolKey('0x1000000000000000000000000000000000000001', USDC, hook);
    expect(low.currency1).toBe(USDC);
    expect(low).toMatchObject({ fee: 10_000, tickSpacing: 200, hooks: hook });
  });

  it('flips direction when selling the token', () => {
    const poolKey = protoV4PoolKey('0xc4354d6b63d07bD04714ea082E362Cd73dCbBFba', USDC, USDC);
    const buy = encodeArcV4ExactInSwap({
      poolKey,
      tokenIn: USDC,
      amountIn: 1n,
      amountOutMinimum: 0n,
    });
    const sell = encodeArcV4ExactInSwap({
      poolKey,
      tokenIn: poolKey.currency1,
      amountIn: 1n,
      amountOutMinimum: 0n,
    });
    expect(buy.inputs[0]).not.toBe(sell.inputs[0]);
  });
});
